function emi(principal, annualRatePct, months){
  if(!(principal>0)||!(months>0)) return null;
  var r=annualRatePct/100/12;
  if(r===0) return principal/months;
  var f=Math.pow(1+r,months);
  return principal*r*f/(f-1);
}
function schedule(principal, annualRatePct, months){
  var e=emi(principal,annualRatePct,months); if(e==null) return null;
  var r=annualRatePct/100/12, bal=principal, rows=[];
  for(var i=1;i<=months;i++){
    var interest=bal*r, principalPart=e-interest; bal=bal-principalPart;
    if(i===months) bal=0;
    rows.push({month:i,payment:e,interest:interest,principal:principalPart,balance:Math.max(bal,0)});
  }
  return rows;
}
